const KONTUR = '#1d1b1a';
const ton = (K, f) => (f > 0 ? hell(K.c, f) : f < 0 ? dunkel(K.c, -f) : K.c);

export function b12Zeichner(S, t, p) {
  const D = B12_DATEN[p.b12];
  if (!D) return;
  if (!S.tex && p.muster && p.muster !== 'uni' && istMuster(p.muster)) S.tex = musterFuellung(S, p.muster);
  // Feine Nadelstreifen als Standarddessin (Caprihose), solange das Musterfeld nichts anderes setzt
  if (p.feinstreifen && !p.muster && (!S.tex || S.m === 'wolle')) { const id = S.id + 'fs'; S.defs.push(`<pattern id="${id}" width="1.9" height="4" patternUnits="userSpaceOnUse"><rect width="0.32" height="4" fill="${hell(S.c, 0.55)}" opacity="0.8"/></pattern>`); S.tex = `url(#${id})`; }
  // Musterfeld aktiv: Musterschlüssel am Typ oder Musterfüllung aus produktSVG (Füllung ist dann nicht die Stofftextur)
  const musterAn = !!S.tex && ((p.muster && p.muster !== 'uni') || S.tex !== `url(#${S.id}t)`);
  // Typ mit Musterzone: Musterfeld nur dort, Bund/Rippe/Besatz bleiben uni
  const nurZone = musterAn && D.regionen.some((r) => r[0] === 'm');
  const K = [S];
  const n = 1 + Math.max(0, ...D.regionen.filter((r) => r[0] === 't' || r[0] === 'r' || r[0] === 'm').map((r) => r[1]));
  for (let i = 1; i < n; i++) K.push(materialDefs(p.farben?.[i - 1] ?? 'grau', p.materialien?.[i - 1] ?? 'baumwolle', S.defs));
  // glatte Strickfläche: Maschenstruktur aus stoff.js weg (Musterfeld bleibt)
  if (p.glatt) K.forEach((k, i) => { if (i > 0 || !musterAn) if (k.m === 'strick' || k.m === 'kaschmir' || k.m === 'merino') k.tex = null; });
  let rip = null;
  if (D.regionen.some((r) => r[0] === 'r')) { rip = S.id + 'rp'; S.defs.push(`<pattern id="${rip}" width="1.15" height="4" patternUnits="userSpaceOnUse"><rect width="0.45" height="4" fill="#000" opacity="0.28"/><rect x="0.5" width="0.25" height="4" fill="#fff" opacity="0.08"/></pattern>`); }
  const clip = S.id + 'b12';
  S.defs.push(`<clipPath id="${clip}"><path d="${D.kontur}" fill-rule="evenodd"/></clipPath>`);
  t.push(`<ellipse cx="50" cy="${D.boden + 1.8}" rx="${Math.min(32, D.breite * 0.45).toFixed(1)}" ry="2.4" fill="#000" opacity="0.08"/>`);
  t.push(`<g clip-path="url(#${clip})">`);
  for (const r of D.regionen) {
    const d = r[r.length - 1];
    if (r[0] === 'k') t.push(`<path d="${d}" fill="${KONTUR}"/>`);
    else if (r[0] === 'f') t.push(`<path d="${d}" fill="${r[1]}"/>`);
    else if (r[0] === 'r') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex && !(nurZone && r[1] === 0)) t.push(`<path d="${d}" fill="${k.tex}"/>`); t.push(`<path d="${d}" fill="url(#${rip})"/>`); }
    else if (r[0] === 'm' && musterAn) { t.push(`<path d="${d}" fill="${ton(S, r[1] === 0 ? r[2] : 0)}"/>`); t.push(`<path d="${d}" fill="${S.tex}"/>`); }
    else if (r[0] === 'm') { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex && !(r[1] === 0 && musterAn)) t.push(`<path d="${d}" fill="${k.tex}"/>`); }
    else { const k = K[r[1]]; t.push(`<path d="${d}" fill="${ton(k, r[2])}"/>`); if (k.tex && !(nurZone && r[1] === 0)) t.push(`<path d="${d}" fill="${k.tex}"/>`); }
  }
  // Licht von links wie alle Stoffe (stoff.js); Glanzlichter stecken schon in den Tonflächen
  t.push(`<path d="${D.kontur}" fill="url(#${S.id}l)" fill-rule="evenodd"/>`);
  t.push('</g>');
}
